import {Stack, Text} from '@primer/react'
import {clsx} from 'clsx'
import styles from './LicenseCount.module.css'
import {LicenseCountProgressBar} from './LicenseCountProgressBar'

export interface LicenseCountProps {
  consumed: number
  available?: number
  consumedBarClassName?: string
  description?: React.ReactNode
}

export function LicenseCount({consumed, available, description, consumedBarClassName}: LicenseCountProps) {
  const showAvailable = typeof available === 'number'

  return (
    <Stack
      direction="vertical"
      gap="condensed"
      padding="none"
      className={clsx(styles.fillWidth)}
      data-testid="license-count"
    >
      <Stack direction="horizontal" gap="normal" padding="none" align="baseline" justify="space-between">
        <Text className="f3 lh-default" size="medium" weight="normal" data-testid="summary-item-amount">
          {consumed.toLocaleString()}
        </Text>
        {showAvailable && (
          <Text className="color-fg-muted" size="medium" data-testid="licensed-count-available">
            {available.toLocaleString()} available
          </Text>
        )}
      </Stack>

      {showAvailable && (
        <LicenseCountProgressBar
          consumedCount={consumed}
          consumedBarClassName={consumedBarClassName}
          totalAvailableCount={available}
        />
      )}

      {!!description && (
        <Text className="color-fg-muted" size="small" data-testid="license-count-desc">
          {description}
        </Text>
      )}
    </Stack>
  )
}

try{ LicenseCount.displayName ||= 'LicenseCount' } catch {}