import {Stack} from '@primer/react'
import {LicenseCountCapped} from './LicenseCountCapped'
import {UsageHint} from './UsageHint'
import {UsageSummary} from './UsageSummary'
import type {HeadingTag} from '../types/heading-tag'
import {LicenseCount} from './LicenseCount'
import {clsx} from 'clsx'
import styles from './EnterpriseCloudUsageSummary.module.css'

export interface EnterpriseCloudUsageSummaryProps {
  canViewMembers: boolean
  enterpriseLicensesConsumed: number
  enterpriseLicensesPurchased: number
  headingAs?: HeadingTag
  isTrial: boolean
  isVolumeLicensed: boolean
  isVssEnabled: boolean
  vssLicensesConsumed: number
  vssLicensesPurchasedWithOverage: number
}
export function EnterpriseCloudUsageSummary(props: EnterpriseCloudUsageSummaryProps) {
  let usageSummaryDescription: string
  if (props.isVolumeLicensed) {
    usageSummaryDescription =
      'Organization members, outside collaborators, and pending invitations consume enterprise licenses.'
    if (props.isVssEnabled) {
      usageSummaryDescription += ' Users matched to a Visual Studio assignment consume a Visual Studio license.'
    }
  } else if (props.isVssEnabled) {
    usageSummaryDescription =
      'Visual Studio subscriptions must first be assigned through the Visual Studio portal. Members without a matched assignment, or licenses consumed beyond the quantity purchased, will count toward the GitHub Enterprise license meter.'
  } else {
    usageSummaryDescription = 'Organization members and outside collaborators consume enterprise licenses.'
  }

  return (
    <UsageSummary
      title="Consumed licenses"
      headingAs={props.headingAs}
      usageHint={
        <UsageHint
          title="Consumed licenses"
          label="About consumed licenses"
          description={usageSummaryDescription}
          learnMoreUrl="https://docs.github.com/en/enterprise-cloud@latest/billing/managing-the-plan-for-your-github-account/about-per-user-pricing"
        />
      }
    >
      {props.isVolumeLicensed || props.isTrial ? (
        <LicenseCountCapped
          enterpriseLicensesConsumed={props.enterpriseLicensesConsumed}
          enterpriseLicensesPurchased={props.enterpriseLicensesPurchased}
          vssLicensesConsumed={props.vssLicensesConsumed}
          vssLicensesPurchased={props.vssLicensesPurchasedWithOverage}
        />
      ) : (
        <Stack className={clsx('width-full', styles.skuStackResponsive)} gap="spacious" padding="none">
          {props.vssLicensesPurchasedWithOverage ? (
            <>
              <LicenseCount
                consumed={props.vssLicensesConsumed}
                description={
                  <>
                    <img
                      width={16}
                      height={16}
                      alt="VSS"
                      className="mr-1"
                      src="/images/modules/site/logos/visualstudio2019-logo.svg"
                      style={{verticalAlign: 'text-bottom'}}
                    />
                    Visual Studio subscriptions
                  </>
                }
                available={props.vssLicensesPurchasedWithOverage}
                consumedBarClassName="bgColor-done-emphasis"
              />
              <LicenseCount consumed={props.enterpriseLicensesConsumed} description="GitHub Enterprise licenses" />
            </>
          ) : (
            <LicenseCount consumed={props.enterpriseLicensesConsumed} />
          )}
        </Stack>
      )}
      {props.vssLicensesPurchasedWithOverage <= 0 && ( // hide here for VSS because the description ends up too long (still in usage hint)
        <div className="f6 color-fg-muted mt-1">{usageSummaryDescription}</div>
      )}
    </UsageSummary>
  )
}

try{ EnterpriseCloudUsageSummary.displayName ||= 'EnterpriseCloudUsageSummary' } catch {}